#!/bin/bash# =============================================================================#  postgres-rejoin-old-primary.sh#  Re-integrate Old Primary as Streaming Standby After Failover#  Sistema Nacional de Cómputo Electoral Bolivia — Módulo 01##  After a failover (manual or automatic), postgres-primary is stale.#  This script safely re-initializes it as a standby of postgres-replica#  (the promoted new primary).##  WHAT IT DOES:#    1. Stops the old primary container (if still running)#    2. Destroys its data volume (prevents split-brain)#    3. Runs pg_basebackup from postgres-replica to a new volume#    4. Writes standby.signal + primary_conninfo → postgres-replica#    5. Starts postgres-primary as a hot standby of postgres-replica##  WHY NOT JUST RESTART THE OLD PRIMARY?#    After a failover, both nodes may have diverging WAL timelines.#    Restarting the old primary as-is risks SPLIT-BRAIN — two writable#    primaries serving conflicting data. The only safe path is a full#    re-sync via pg_basebackup from the new primary.##  Run from the 01-clusters-bases-failover/ directory:#    bash scripts/postgres-rejoin-old-primary.sh           ← interactive#    bash scripts/postgres-rejoin-old-primary.sh --force   ← skip prompts# =============================================================================set -eFORCE=falsefor arg in "$@"; do    [ "$arg" = "--force" ] && FORCE=truedoneOLD_PRIMARY_CONTAINER="${OLD_PRIMARY_CONTAINER:-postgres-primary}"NEW_PRIMARY_CONTAINER="${NEW_PRIMARY_CONTAINER:-postgres-replica}"NEW_PRIMARY_PORT="${NEW_PRIMARY_PORT:-5432}"REPLICATION_USER="${REPLICATION_USER:-replicator}"REPLICATION_PASSWORD="${REPLICATION_PASSWORD:-replicator_password}"PG_USER="${PG_USER:-oep_user}"PG_DB="${PG_DB:-oep_oficial}"# Detect Docker Compose project name from directorySCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"MODULE_DIR="$(dirname "$SCRIPT_DIR")"PROJECT_NAME="$(basename "$MODULE_DIR")"OLD_PRIMARY_VOLUME="${PROJECT_NAME}_postgres_primary_data"NETWORK_NAME="${PROJECT_NAME}_oep-network"echo "======================================================================"echo "  PostgreSQL Failover — Re-join Old Primary as Standby"echo "  Sistema Nacional de Cómputo Electoral Bolivia"echo "======================================================================"echo ""echo "  Detected project   : $PROJECT_NAME"echo "  Old primary        : $OLD_PRIMARY_CONTAINER  (will become standby)"echo "  New primary        : $NEW_PRIMARY_CONTAINER  (data source)"echo "  Volume to replace  : $OLD_PRIMARY_VOLUME"echo "  Docker network     : $NETWORK_NAME"echo ""echo "  WARNING: This operation is IRREVERSIBLE."echo "  The old primary's data volume will be destroyed and rebuilt."echo "  Ensure the new primary ($NEW_PRIMARY_CONTAINER) is stable and running."echo ""# ── Safety check 1: New primary must be writable ──echo "Verifying $NEW_PRIMARY_CONTAINER is a writable PRIMARY..."if ! docker ps --format '{{.Names}}' | grep -q "^${NEW_PRIMARY_CONTAINER}$"; then    echo "ERROR: $NEW_PRIMARY_CONTAINER is not running."    echo "       Cannot perform rejoin without a running new primary."    exit 1fiIN_RECOVERY=$(docker exec "$NEW_PRIMARY_CONTAINER" \    psql -U "$PG_USER" -d "$PG_DB" -tAq \    -c "SELECT pg_is_in_recovery();" 2>/dev/null || echo "error")if [ "$IN_RECOVERY" = "error" ]; then    echo "ERROR: Cannot connect to $NEW_PRIMARY_CONTAINER."    echo "       Ensure it is running and accepting connections."    exit 1fiif [ "$IN_RECOVERY" = "t" ]; then    echo "ERROR: $NEW_PRIMARY_CONTAINER is still in STANDBY mode."    echo "       Promote it first: bash scripts/postgres-promote-replica.sh"    exit 1fiecho "OK: $NEW_PRIMARY_CONTAINER is a writable PRIMARY."echo ""# ── Safety check 2: Old primary must NOT be running as a primary ──if docker ps --format '{{.Names}}' | grep -q "^${OLD_PRIMARY_CONTAINER}$"; then    OLD_RECOVERY=$(docker exec "$OLD_PRIMARY_CONTAINER" \        psql -U "$PG_USER" -d "$PG_DB" -tAq \        -c "SELECT pg_is_in_recovery();" 2>/dev/null || echo "down")    if [ "$OLD_RECOVERY" = "f" ]; then        echo "WARNING: $OLD_PRIMARY_CONTAINER is STILL RUNNING as a PRIMARY."        echo "         If this is the old primary after failover, there may be a"        echo "         SPLIT-BRAIN situation. Proceeding will stop and wipe it."        echo ""    fifiif [ "$FORCE" = "true" ]; then    echo "  --force flag detected. Skipping interactive confirmation."else    read -p "Type YES to destroy the old primary volume and rebuild as standby: " CONFIRM    if [ "$CONFIRM" != "YES" ]; then        echo "Aborted."        exit 0    fifiecho ""# ── Step 1: Stop and remove old primary container ──echo "Step 1 — Stopping $OLD_PRIMARY_CONTAINER..."docker stop "$OLD_PRIMARY_CONTAINER" 2>/dev/null && echo "  Container stopped." \    || echo "  Container was already stopped."docker rm "$OLD_PRIMARY_CONTAINER" 2>/dev/null && echo "  Container removed." \    || echo "  Container already removed."# ── Step 2: Remove and recreate the data volume ──echo ""echo "Step 2 — Removing stale data volume: $OLD_PRIMARY_VOLUME..."docker volume rm "$OLD_PRIMARY_VOLUME" 2>/dev/null && echo "  Volume removed." \    || echo "  Volume did not exist (OK)."docker volume create "$OLD_PRIMARY_VOLUME"echo "  New empty volume created: $OLD_PRIMARY_VOLUME"# ── Step 3: pg_basebackup from new primary ──echo ""echo "Step 3 — Running pg_basebackup from $NEW_PRIMARY_CONTAINER..."echo "         (This may take a moment depending on database size)"docker run --rm \    --network "$NETWORK_NAME" \    -v "${OLD_PRIMARY_VOLUME}:/pgdata" \    -e PGPASSWORD="$REPLICATION_PASSWORD" \    postgres:16 \    pg_basebackup \        -h "$NEW_PRIMARY_CONTAINER" \        -p "$NEW_PRIMARY_PORT" \        -U "$REPLICATION_USER" \        -D /pgdata \        -Fp -Xs -P \        --checkpoint=fastecho "  pg_basebackup complete."# ── Step 4: Write standby configuration ──echo ""echo "Step 4 — Writing standby.signal and primary_conninfo..."docker run --rm \    -v "${OLD_PRIMARY_VOLUME}:/pgdata" \    postgres:16 bash -c "        touch /pgdata/standby.signal        cat >> /pgdata/postgresql.auto.conf << 'STANDBY_CONF'# ── Standby configuration — added by postgres-rejoin-old-primary.sh ──primary_conninfo = 'host=${NEW_PRIMARY_CONTAINER} port=${NEW_PRIMARY_PORT} user=${REPLICATION_USER} password=${REPLICATION_PASSWORD} application_name=rejoined_standby sslmode=prefer'recovery_target_timeline = 'latest'STANDBY_CONF        chown -R 999:999 /pgdata        chmod 700 /pgdata        echo '  standby.signal written.'        echo '  primary_conninfo written → ${NEW_PRIMARY_CONTAINER}:${NEW_PRIMARY_PORT}'    "# ── Step 5: Start old primary as standby ──echo ""echo "Step 5 — Starting $OLD_PRIMARY_CONTAINER as standby..."cd "$MODULE_DIR"docker compose up -d "$OLD_PRIMARY_CONTAINER"# ── Step 6: Verify ──echo ""echo "Waiting 20s for $OLD_PRIMARY_CONTAINER to start and connect to new primary..."sleep 20REJOIN_STATUS=$(docker exec "$OLD_PRIMARY_CONTAINER" \    psql -U "$PG_USER" -d "$PG_DB" -tAq \    -c "SELECT pg_is_in_recovery();" 2>/dev/null || echo "error")echo ""if [ "$REJOIN_STATUS" = "t" ]; then    echo "======================================================================"    echo "  REJOIN SUCCESSFUL"    echo "======================================================================"    echo ""    echo "  $OLD_PRIMARY_CONTAINER is now a STANDBY of $NEW_PRIMARY_CONTAINER"    echo "  (pg_is_in_recovery() = true)"    echo ""    echo "Verify replication from new primary:"    docker exec "$NEW_PRIMARY_CONTAINER" \        psql -U "$PG_USER" -d "$PG_DB" \        -c "SELECT application_name, client_addr, state, sync_state FROM pg_stat_replication;" \        2>/dev/null || true    echo ""    echo "Note: Hostnames are now REVERSED (postgres-primary is the standby,"    echo "      postgres-replica is the primary). This is expected after failover."    echo "      For a clean hostname reset: docker compose down -v && restart."elif [ "$REJOIN_STATUS" = "f" ]; then    echo "WARNING: $OLD_PRIMARY_CONTAINER started but appears to be a PRIMARY."    echo "         This should not happen. Check logs:"    echo "         docker logs $OLD_PRIMARY_CONTAINER"else    echo "Could not verify $OLD_PRIMARY_CONTAINER status yet."    echo "It may still be starting. Check after a moment:"    echo "  docker exec $OLD_PRIMARY_CONTAINER psql -U $PG_USER -d $PG_DB -c \"SELECT pg_is_in_recovery();\""    echo "  docker logs $OLD_PRIMARY_CONTAINER"fi